def test_an_oversized_upload_is_rejected():
    """An upload over the size limit is refused."""
    with pytest.raises(UploadRejected, match="too large"):
        validate_upload("report.pdf", 50 * 1024 * 1024)


def test_the_stored_name_is_lowercased():
    """The stored name is the filename lowercased."""
    assert validate_upload("Report.PDF", 1024) == "report.pdf"


@pytest.mark.parametrize("extension", ["PDF", "Png", "csv"])
def test_an_allowed_extension_is_accepted_regardless_of_case(extension):
    """Extensions are matched case-insensitively."""
    validate_upload(f"report.{extension}", 1024)


def test_a_disallowed_extension_is_rejected():
    """An upload with an extension outside the allow list is refused."""
    with pytest.raises(UploadRejected, match="pdf, .png or .csv"):
        validate_upload("report.docx", 1024)


@pytest.mark.parametrize("filename", ["../report.pdf", "sub/report.pdf", r"sub\report.pdf"])
def test_a_filename_with_a_path_separator_is_rejected(filename):
    """A filename containing either kind of path separator is refused, not repaired."""
    with pytest.raises(UploadRejected, match="path separator"):
        validate_upload(filename, 1024)


def test_a_filename_starting_with_a_dot_is_rejected():
    """A dotfile-style filename is refused."""
    with pytest.raises(UploadRejected, match="start with a dot"):
        validate_upload(".report.pdf", 1024)

